mapper.select:
SELECT  FROM combination_review_run r
INNER JOIN combination_review c ON c.id = r.review_id
WHERE r.id = #{runId} AND r.review_id = #{reviewId} AND c.owner_account_id = #{ownerId}

SELECT  FROM combination_review_run r
INNER JOIN combination_review c ON c.id = r.review_id
WHERE r.review_id = #{reviewId} AND c.owner_account_id = #{ownerId}
AND r.id < #{beforeId}
ORDER BY r.id DESC LIMIT #{limit}

mapper.update:
UPDATE combination_review_run SET status = #{status}, analysis_json = #{analysisJson}, failure_code = #{failureCode}, finished_at = #{finishedAt}
WHERE id = #{runId} AND status = 'RUNNING'
AND execution_started_at > DATE_SUB(#{finishedAt}, INTERVAL 20 MINUTE)

mapper.select:
SELECT id FROM combination_review_run
WHERE status = 'QUEUED' AND queue_expires_at > #{now} AND next_publish_at <= #{now}
ORDER BY id LIMIT 20

mapper.update:
UPDATE combination_review_run r INNER JOIN combination_review c ON c.id = r.review_id
INNER JOIN account a ON a.id = c.owner_account_id
SET r.status = 'RUNNING', r.runner_instance_id = #{runnerId}, r.execution_started_at = #{now}
WHERE r.id = #{runId} AND r.status = 'QUEUED' AND r.queue_expires_at > #{now}
  AND a.deleted_at IS NULL AND a.suspended_at IS NULL
